import java.util.*;

class Solution {
  public int countPairs(int[] nums) {
    Map<Integer, Integer> seen = new HashMap<>();
    int answer = 0;
    for (int value : nums) {
      for (int candidate : variants(value, 1)) answer += seen.getOrDefault(candidate, 0);
      seen.merge(value, 1, Integer::sum);
    }
    return answer;
  }

  private Set<Integer> variants(int value, int swaps) {
    char[] digits = Integer.toString(value).toCharArray();
    Set<Integer> result = new HashSet<>();
    result.add(value);
    for (int i = 0; i < digits.length; i++)
      for (int j = i + 1; j < digits.length; j++) {
        char t = digits[i];
        digits[i] = digits[j];
        digits[j] = t;
        result.add(Integer.parseInt(new String(digits)));
        digits[j] = digits[i];
        digits[i] = t;
      }
    return result;
  }
}
